\begin{eqnarray}\label{eq:optimization_problem}
\min_{x\in \R^d} \pbr{  F(x) \equiv f(x) + R(x) },
\end{eqnarray}

\begin{equation}
    \label{eq:sgd-proximal-iterates}
    x_0 \in \R^d, \quad x_{k+1} = \prox_{\gamma_k R} \br{ x_k - \gamma_k g_k },
\end{equation}

where $\br{\gamma_k}_k$ is a sequence of step sizes.  This estimate $g_k$
can take on many different forms depending on the problem of interest. Here we list a few.


\paragraph{Notation.}   The Bregman divergence associated with $f$ is the mapping $$D_{f} (x, y) \; \eqdef \; f(x) - f(y) - \ev{ \nabla f(y), x - y }, \quad x,y\in R^d$$ and the proximal operator of $\gamma R$ is the function $$\prox_{\gamma R} \br{x} \; \eqdef \; \argmin_u \left\{ \gamma R(x) + \frac{1}{2} \norm{x-u}^2\right\}.$$ Let $[n] \eqdef \left\{1,\dots,n\right\}$. 


\begin{assumption} \label{asm:function-class}
The function $f$ is  $L$--smooth and convex:
\begin{align}
f(y) & \leq f(x) + \langle \nabla f(x), y - x \rangle + \frac{L}{2} \norm{y-x}^2,  \quad \mbox{for all }x,y \in \R^d, \label{eq:Lsmooth}\\
f(y )& \geq f(x) + \langle \nabla f(x), y - x \rangle, \quad \mbox{for all }x,y \in \R^d. \label{eq:convex}
\end{align}
The function $R$ is convex:
\begin{equation}\label{eq:R-convex}
R(\alpha x + (1- \alpha) y) \geq \alpha R(x) + (1-\alpha) R(y), \quad \mbox{for all }x,y \in \R^d, \alpha \in [0,\,1].
\end{equation}

\end{assumption}

\begin{assumption}[Assumption 4.1 in \cite{Gorbunov19}]\label{asm:main_assumption}
Consider the iterates $\br{x_k}_k$ and gradients $\br{g_k}_k$ in \eqref{eq:sgd-proximal-iterates}.
    \begin{enumerate}
        \item The gradient estimates are unbiased:
        \begin{equation}
            \label{eq:asm-gradient-unbiased}
            \ec{g_k \mid x_k} = \nabla f(x_k).
        \end{equation}
        \item There exist constants $A,B,C,D_1, D_2, \rho \geq 0$, and a sequence of random variables $\sigma^2_k \geq 0 $  such that:
        \begin{align}
            \label{eq:asm-gradient-opt-distance}
            \ec{ \norm{g_k - \nabla f(x_\ast)}^2 \mid x_k } &\leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1, \\
            \label{eq:asm-decreasing-noise}
            \ec{ \sigma_{k+1}^2 \mid x_k } &\leq \br{ 1 - \rho } \sigma_k^2 + 2 C D_{f} (x_k, x_\ast) + D_2.
        \end{align}
    \end{enumerate} 
\end{assumption}

\begin{definition}
    Given a stepsize $\gamma > 0$, the prox-grad mapping is defined as:
    \begin{equation}
        T_{\gamma} (x) \eqdef \prox_{\gamma R} \br{x - \gamma \nabla f(x)}.
    \end{equation}
\end{definition}

