\begin{theorem}
    \label{thm:main-prox-dec}
    Suppose that Assumptions~\ref{asm:function-class} and~\ref{asm:main_assumption} hold. Let $M \eqdef B/\rho$ and let $(\gamma_k)_{k\geq 0}$ be a decreasing, strictly positive sequence of step sizes chosen such that
    \[ 0 < \gamma_0 < \min \left\{ \frac{1}{2 (A + MC)}, \frac{1}{L} \right\}. \]
The iterates given by \eqref{eq:sgd-proximal-iterates} satisfy
    \begin{align}
        \label{eq:main-thm-convergence-bound}
        \ec{F(\bar{x}_t) - F(x_\ast)} \leq \frac{\sqn{x_0 - x_*} + 2\gamma_0\br{\delta_0 + \gamma_0M\sigma_0^2} + 2\br{D_1 + 2 M D_2}\sum \limits_{k=0}^{t-1}\gamma_k^2}{2\sum \limits_{i=0}^{t-1}\br{1 - 2\gamma_i\br{A+MC}} \gamma_i},
    \end{align}
    where $\bar{x}_t \eqdef \sum\limits_{k=0}^{t-1} \frac{\br{ 1 - 2\gamma_k(A+MC)}  \gamma_k}{\sum \limits_{i=0}^{t-1}\br{1 - 2\gamma_i(A+MC)} \gamma_i}x_k$ and ${\delta_0 \eqdef F(x_0) - F(x_\ast)}$.
\end{theorem}

