\subsection{Proof of Lemma~\ref{lemma:atchade-functional-value-bound}}
\label{app:sec:prooflemma}
%Here
%\begin{lemma}
% \[  F(p) - F(z)  \leq -\frac{1}{2\gamma}\sqn{p - z } - \frac{1}{\gamma}  \ev{x - \gamma \nabla f(x) - y, p-z} + \frac{1}{2\gamma}\sqn{z - x}. \]
%\end{lemma}

This proof is based on the proof of  Lemma~8 in \cite{Atchade17}. The only difference is that in  \cite{Atchade17} the authors assume that $f$ is convex.
Indeed, using the convexity of $f$
 \[f(x) -f(x_\ast) \geq  - \langle \nabla f(x), x_\ast - x \rangle\]
%\[f(x)- f(z) \leq  - \dotprod{\nabla f(x), z-x} \]
in combination with~\eqref{eq:2ndproxtheo} where $z = x_\ast$ gives
\begin{align*}
f(x)+g(p)- F(x_\ast) & \leq -\frac{1}{\gamma} \dotprod{p - y, p -x_\ast}- \dotprod{\nabla f(x), x_\ast-x}. 
\end{align*}
Now using smoothness
\[ f(p) -f(x) \leq \dotprod{\nabla f(x),p -x} + \frac{1}{2\gamma} \norm{p-x}^2,\]
gives
%& \leq \frac{1}{\gamma} \dotprod{ y-p +\gamma \nabla f(x) , p -z}- \dotprod{\nabla f(x), p-x}+\dotprod{\nabla f(x),p -x} + \frac{1}{2\gamma} \norm{p-x}^2\\
\begin{align}
F(p)- F(x_\ast) 
&\leq-\frac{1}{\gamma} \dotprod{p - y, p -x_\ast}- \dotprod{\nabla f(x), x_\ast-x} +\dotprod{\nabla f(x),p -x} + \frac{1}{2\gamma} \norm{p-x}^2 \nonumber \\
&= -\frac{1}{\gamma} \dotprod{p - y, p -x_\ast}+\dotprod{\nabla f(x),p -x_\ast} + \frac{1}{2\gamma} \norm{p-x}^2 \nonumber \\
&= -\frac{1}{\gamma} \dotprod{p -\gamma \nabla f(x)- y, p -x_\ast} + \frac{1}{2\gamma} \norm{p-x}^2 \nonumber  \\
&= -\frac{1}{\gamma} \dotprod{p-x+x -\gamma \nabla f(x)- y, p -x_\ast} + \frac{1}{2\gamma} \norm{p-x}^2 \nonumber \\
&= -\frac{1}{\gamma} \dotprod{p-x, p -x_\ast} -\frac{1}{\gamma} \dotprod{x -\gamma \nabla f(x)- y, p -x_\ast} + \frac{1}{2\gamma} \norm{p-x}^2 . \label{eq:tenaoineria}
\end{align}
Using that
\begin{equation}
-2 \dotprod{p-x, p -x_\ast}  + \norm{p-x}^2 = -\norm{p-x_\ast}^2 + \norm{z-x}^2,
\end{equation}
in combination with~\eqref{eq:tenaoineria} gives 
 \[  F(p) - F(x_\ast)  \leq -\frac{1}{2\gamma}\sqn{p - x_\ast} - \frac{1}{\gamma}  \ev{x - \gamma \nabla f(x) - y, p-x_\ast} + \frac{1}{2\gamma}\sqn{x_\ast - x}. \]
 Now it remains to multiply both sides by $-2\gamma$ to arrive at~\eqref{eq:atchade-lemma}. 


