\begin{lemma}[Bounding the gradient variance] Assuming that the $g_k$ are unbiased and that Assumption~\ref{asm:main_assumption} holds, we have
    \begin{equation}
        \label{eq:lma-gradient-variance}
        \ecn{g_k - \nabla f(x_k)}  \leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1
    \end{equation}
\end{lemma}

\begin{proof}
    Starting from the left hand side of \eqref{eq:lma-gradient-variance}, we have
    \begin{align*}
        \ecn{g_k - \nabla f(x_k)} &= \ecn{ g_k - \nabla f(x_\ast) - \br{ \nabla f(x_k) - \nabla f(x_\ast) } } \\
        &= \ecn{ g_k - \nabla f(x_\ast) - \ec{ g_k - \nabla f(x_\ast) } } \\
        &\leq \ecn{g_k - \nabla f(x_\ast)} \leq 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1,
    \end{align*}
    where we used that $\ecn{ X - \ec{X} } = \ecn{X} - \norm{\ec{X}}^2 \leq \ecn{X}$ for any random variable $X$.
\end{proof}

\begin{lemma}
