    \begin{equation}
        \label{eq:atchade-lemma}
        - 2 \gamma \br{ F(p) - F(x_\ast) } \geq \sqn{p - z } + 2  \ev{p - x_\ast, x - \gamma \nabla f(x) - y} - \sqn{x_\ast - x}.
    \end{equation}
\end{lemma}

\begin{proof}
