\begin{lemma}
    For any $x \in \R^d$ and minimizer $x_\ast$ of $F$ we have,
    \begin{equation}
        \label{eq:bregman-divergence-bound}
        D_{f} (x, x_\ast) \leq F(x) - F(x_\ast).
    \end{equation}
\end{lemma}

\begin{proof}
    Let $x_\ast$ be a minimizer of $F$. Using \eqref{eq:atchade-lemma} from Lemma~\ref{lemma:atchade-functional-value-bound} with $y = x_k - \gamma_k g_k$, $x = x_k$ and $\gamma = \gamma_k$ gives
    \begin{align*}
        -2 \gamma_k \br{ F(x_{k+1}) - F(x_\ast) } &\geq \norm{x_{k+1} - x_\ast}^2 - \norm{x_k - x_\ast}^2 + 2 \gamma_k \ev{ x_{k+1} - x_\ast, g_k - \nabla f(x_k) }.
    \end{align*}
    Multiplying both sides by $-1$ results in
    \begin{align}        
        \label{eq:gen-prox-dec-proof-init}
        2 \gamma_k \br{F(x_{k+1}) - F(x_\ast)} &\leq \sqn{x_k - x_\ast} - \sqn{x_{k+1} - x_\ast} + 2 \gamma_k \ev{x_{k+1} - x_\ast, \nabla f(x_k) - g_k}.
    \end{align}
    Now focusing on the last term in the above and consider the straightforward decomposition
    \begin{align}
        \label{eq:gen-prox-dec-proof-0}
        \ev{x_{k+1} - x_\ast, \nabla f(x_k) - g_k} &= \ev{x_{k+1} - T_{\gamma_k} (x_k), \nabla f(x_k) - g_k } + \ev{T_{\gamma_k} (x_k) - x_\ast, \nabla f(x_k) - g_k}.
     \end{align}
    By Cauchy Schwartz we have that
    \begin{align}
        \label{eq:gen-prox-dec-proof-1}
        \ev{x_{k+1} - T_{\gamma_k} (x_k), \nabla f(x_k) - g_k} \leq \norm{ x_{k+1} - T_{\gamma_k} (x_k) } \norm{g_k - \nabla f(x_k)}.
    \end{align}
    Now using the nonexpansivity of the proximal operator
    \begin{align*}
        \norm{x_{k+1} - T_{\gamma_k} (x_k)} &= \norm{ \prox_{\gamma_k R} \br{ x_k - \gamma_k g_k } - \prox_{\gamma_k R} \br{x_k - \gamma_k \nabla f(x_k)} } \\
        &\leq \norm{ \br{x_k - \gamma_k g_k} - \br{x_k - \gamma_k \nabla f(x_k)} } = \gamma_k \norm{g_k - \nabla f(x_k)}.
    \end{align*}
    Using this in \eqref{eq:gen-prox-dec-proof-1}, we have
    \begin{align}
        \label{eq:gen-prox-dec-proof-2}
        \ev{x_{k+1} - T_{\gamma_k} (x_k), \nabla f(x_k) - g_k} \leq \gamma_k \norm{g_k - \nabla f(x_k)}^2.
    \end{align}
    Using \eqref{eq:gen-prox-dec-proof-2} in \eqref{eq:gen-prox-dec-proof-0} and taking expectation conditioned on $x_k$, and using $\ec[k]{\cdot} \eqdef \ec{\cdot \; | \; x_k}$ for shorthand, we have
    \begin{align}
        \label{eq:gen-prox-dec-proof-2-1}
        \ec[k]{\ev{x_{k+1} - x_\ast, g_k - \nabla f(x_k)}} &\leq \gamma_k \cdot \ecn[k]{g_k - \nabla f(x_k)} + \ev{ T_{\gamma_k} (x_k) - x_\ast, \underbrace{\ec[k]{\nabla f(x_k) - g_k}}_{= 0} } \nonumber \\
        &= \gamma_k \cdot \ecn[k]{g_k - \nabla f(x_k)}.
    \end{align}
	Let $r_k \eqdef x_k-x_\ast.$    Taking expectation conditioned on $x_k$ in \eqref{eq:gen-prox-dec-proof-init} and using \eqref{eq:gen-prox-dec-proof-2-1}, we have
    \begin{align*}
        2 \gamma_k \ec[k]{ F(x_{k+1} - F(x_\ast)) } &\leq \sqn{r_k} - \ecn[k]{r_{k+1}} + 2 \gamma_k^2 \ecn[k]{g_k - \nabla f(x_k)}.
    \end{align*}
    Using \eqref{eq:asm-gradient-opt-distance} from Assumption~\ref{asm:main_assumption} we have
    \begin{align*}
        2 \gamma_k \ec[k]{ F(x_{k+1}) - F(x_\ast) } &\leq \sqn{r_k} - \ecn[k]{r_{k+1}} + 2 \gamma_k^2 \br{ 2 A D_{f} (x_k, x_\ast) + B \sigma_k^2 + D_1}.
    \end{align*}
    Let $V_k \eqdef \sqn{r_k} + 2 M \gamma_k^2 \sigma_{k}^2$ where $M = \frac{B}{\rho}$, then
    \begin{align}
        \label{eq:gen-prox-dec-proof-3}
        \begin{split}
            2 \gamma_k \ec[k]{ F(x_{k+1}) - F(x_\ast) } \leq V_k &- \ec[k]{V_{k+1}} + 4 \gamma_k^2 A D_{f} (x_k, x_\ast) + 2 \gamma_k^2 D_1 \\
            &+ \gamma_k^2 \br{ 2B - 2 M } \sigma_{k}^2 + 2 M \gamma_{k+1}^2 \ec{\sigma_{k+1}^2}.
        \end{split}
    \end{align}
Since $\gamma_{k+1} \leq \gamma_k$ we have that
	\begin{align}
        \label{eq:gen-prox-dec-proof-3.1}
        \begin{split}
            2 \gamma_{k+1} \ec[k]{ F(x_{k+1}) - F(x_\ast) } \leq V_k &- \ec[k]{V_{k+1}} + 4 \gamma_k^2 A D_{f} (x_k, x_\ast) + 2 \gamma_k^2 D_1 \\
            &+ \gamma_k^2 \br{ 2B - 2 M } \sigma_{k}^2 + 2 M \gamma_k^2 \ec{\sigma_{k+1}^2}.
        \end{split}
    \end{align}

    Using \eqref{eq:asm-decreasing-noise} from Assumption~\ref{asm:main_assumption}, we have
        \begin{align}
        \label{eq:gen-prox-dec-proof-4}
            2 \gamma_k^2 \br{B - M} \sigma_k^2 + 2 M \gamma_k^2 \ec[k]{\sigma_{k+1}^2} & \leq 2 \gamma_k^2 \br{ B - M + M (1 - \rho) } \sigma_k^2 + 4 M \gamma_k^2 C D_{f} (x_k, x_\ast)\nonumber  \\
            &\quad + 2 M \gamma_k^2 D_2
 \nonumber \\
       & = 2 \gamma_k^2 \underbrace{\br{ B - \rho M}}_{= 0} \sigma_k^2 + 4 M \gamma_k^2 C D_{f} (x_k, x_\ast) +2 M \gamma_k^2 D_2 \nonumber \\
       & \leq 4 M \gamma_k^2 C D_{f} (x_k, x_\ast) +2 M \gamma_k^2 D_2.
    \end{align}
%    \begin{align}
%        \label{eq:gen-prox-dec-proof-4}
%        \begin{split}
%            2 \gamma_k^2 \br{B - M} \sigma_k^2 + 2 M \gamma_k^2 \ec[k]{\sigma_{k+1}^2} \leq 2 \gamma_k^2 \br{ B - M + M (1 - \rho) } \sigma_k^2 &+ 4 M \gamma_k^2 C D_{f} (x_k, x_\ast) \\
%            &+ 2 M \gamma_k^2 D_2
%        \end{split} \nonumber \\
%        = 2 \gamma_k^2 \underbrace{\br{ B - \rho M}}_{= 0} \sigma_k^2 + 4 M \gamma_k^2 C D_{f} (x_k, x_\ast) &+2 M \gamma_k^2 D_2 \nonumber \\
%        \leq 4 M \gamma_k^2 C D_{f} (x_k, x_\ast) &+2 M \gamma_k^2 D_2.
%    \end{align}
    Using \eqref{eq:gen-prox-dec-proof-4} in \eqref{eq:gen-prox-dec-proof-3} gives
    \begin{align}
        \label{eq:gen-prox-dec-proof-5}
        2 \gamma_{k+1} \ec[k]{ F(x_{k+1}) - F(x_\ast) } &\leq V_k - \ec[k]{V_{k+1}} + 2 \gamma_k^2 \br{ 2 A + 2 M C } D_{f} (x_k, x_\ast) + 2 \gamma_k^2 \br{ D_1 + M D_2 }.
    \end{align}
    Let $\eta \eqdef 2A + 2 M C$. Using \eqref{eq:bregman-divergence-bound} in \eqref{eq:gen-prox-dec-proof-5} we have,
    \begin{align*}
        2 \gamma_{k+1} \ec[k]{ F(x_{k+1}) - F(x_\ast) } &\leq V_k - \ec[k]{V_{k+1}} + 2 \gamma_k^2 \eta \br{ F(x_k) - F(x_\ast) } + 2 \gamma_k^2 \br{ D_1 + M D_2 }.
    \end{align*}
    Using the abbreviation $\delta_k = F(x_k) - F(x_\ast)$ gives
    \begin{align*}
        2 \gamma_{k+1} \ec[k]{\delta_{k+1}} &\leq V_{k} - \ec[k]{V_{k+1}} + 2 \gamma_k^2 \eta \delta_k + 2 \gamma_k^2 \br{D_1 + M D_2}.
    \end{align*}
    Taking expectation,
   \begin{align*}
        2 \gamma_{k+1} \ec{\delta_{k+1}} &\leq \ec{V_{k}} - \ec{V_{k+1}} + 2 \gamma_k^2 \eta \ec{\delta_k} + 2 \gamma_k^2 \br{D_1 + M D_2},
    \end{align*}
 summing over $k =0,\ldots, t-1$ and using telescopic cancellation gives
    \begin{align*}
        2  \sum_{k=1}^{t}\gamma_k\ec{\delta_{k}} &\leq V_{0} - \ec{V_{t}} + 2  \eta \sum_{k=0}^{t-1}\gamma_k^2 \ec{\delta_k} + 2 \br{ D_1 + M D_2 } \sum_{k=0}^{t-1}\gamma_k^2.
    \end{align*}
Adding $2\gamma_0\delta_0$ to both sides of the above inequality and rearranging,
\begin{align*}
2  \sum_{k=0}^{t-1}\gamma_k(1-\eta\gamma_k)\ec{\delta_{k}} &\leq V_{0} - \ec{V_{t}} + 2 \gamma_0 \delta_0 + 2 \br{ D_1 + M D_2 } \sum_{k=0}^{t-1}\gamma_k^2
\end{align*}

    where we also used that $V_t \geq 0$ and $\delta_t \geq 0.$

    By the choice of $\gamma_0$ we have $1 - \gamma_0 \eta > 0$, and since $(\gamma_i)_i$ is a decreasing sequence, we have $1 - \gamma_i \eta > 0$ for all $i$. Hence dividing both sides by $2\sum\limits_{i=0}^{t-1}\br{1 - \gamma_i\eta} \gamma_i$, we have
    \begin{align*}
        \sum_{k=0}^{t-1} w_k \ec{\delta_k} \leq \frac{V_0 + 2 \gamma_0 \delta_0}{2\sum_{i=0}^{t-1}\br{1 - \gamma_i\eta} \gamma_i} + \br{D_1 + 2 M D_2} \frac{\sum_{k=0}^{t-1}\gamma_k^2}{\sum_{i=1}^{t}\br{1-\gamma_i\eta}\gamma_i},
    \end{align*}
    where $w_k \eqdef \frac{\br{ 1 - \gamma_k \eta }  \gamma_k}{\sum_{i=0}^{t-1}\br{1 - \gamma_i\eta} \gamma_i}$ for all $k \in \left\{0,\dots,t-1\right\}$. Note that $\sum_{k=0}^{t-1} w_k = 1$ and $w_k \geq 0$ for all $k \in \left\{0,\dots,t-1\right\}$. Hence, since $F$ is convex, we can use Jensen's inequality to conclude
    \begin{align*}
        \ec{F(\bar{x}^k) - F(x_\ast)} &= \ec{F\br{ \sum\limits_{k=0}^{t-1} w_k x_k} - F(x_\ast)} \\
        &\leq \sum_{k=0}^{t-1}w_k \ec{\delta_k} \leq \frac{V_0 + 2\gamma_0 \delta_0}{2\sum_{i=0}^{t-1}\br{1 - \gamma_i\eta} \gamma_i} + \frac{\br{D_1 + 2 M D_2} \sum_{k=0}^{t-1}\gamma_k^2}{\sum_{i=0}^{t-1}\br{1-\gamma_i\eta}\gamma_i}.
    \end{align*}
    Writing out the definition of $\delta_0$ yields the theorem's statement.
\end{proof}

